const VOICE_PAIRS = [
  ['female_1', 'male_1'], ['male_2', 'female_2'], ['female_3', 'male_3'],
  ['male_1', 'female_3'], ['female_2', 'male_2'],
];

function interviewSet({ slug, title, topic, cefr, voices, dialogue, questions }) {
  const id = `listening-pilot-v1.interview.${slug}`;
  return {
    id,
    revision: 1,
    type: 'interview',
    title,
    topic,
    cefr,
    provenance: 'original',
    audio: { path: `/audio/listening/listening-pilot-v1/interview/${slug}-r1.mp3` },
    script: dialogue.map((text, index) => ({
      role: index % 2 === 0 ? 'interviewer' : 'guest',
      voiceSlot: voices[index % 2],
      text,
    })),
    task: {
      questions: questions.map((question, index) => ({
        id: `${id}.q${index + 1}`,
        ...question,
      })),
    },
  };
}

